// Normaliza el body del widget de chat (incluye datos del visitante).
const body = $input.first().json.body || $input.first().json || {};
const message = (body.message || '').toString().trim();
const sessionId = (body.sessionId || 'anon-' + $execution.id).toString();
const visitor = body.visitor || {};
const visitorName = (visitor.name || '').toString().trim();
const visitorPhone = (visitor.phone || '').toString().trim();

return [{ json: { message, sessionId, visitorName, visitorPhone } }];

// Extrae { reasoning, messages } del agente y arma la respuesta limpia.
let raw = $input.first().json.output ?? $input.first().json.text ?? '';
let messages = [];

try {
  const clean = raw.toString().replace(/```json|```/g, '').trim();
  const parsed = JSON.parse(clean);
  if (Array.isArray(parsed.messages)) {
    messages = parsed.messages.filter((m) => (m || '').toString().trim());
  }
} catch (e) {
  messages = [raw.toString().trim()];
}

if (messages.length === 0) {
  messages = ['Gracias por escribir. ¿En qué puedo ayudarte sobre Danny?'];
}

const reply = messages.join('\n\n');
const n = $('Normalizar Datos').first().json;

return [{ json: { reply, messages, sessionId: n.sessionId, message: n.message, visitorName: n.visitorName, visitorPhone: n.visitorPhone } }];

// Respaldo si el agente falla: nunca exponemos el error.
const reply = 'Ahora mismo no puedo responderte bien 😅. Escríbele a Danny directo: WhatsApp +58 422-4543543 o dannyendara28@gmail.com. ¡Te responderá rápido!';
return [{ json: { reply, messages: [reply] } }];
